-- =======================================================
-- 850匯入 / DB install — 指定道具賦予狀態 (Item Designated Status)
-- 來源：atu381.w_指定道具賦予狀態 (158 rows)
-- 目標：850 原生正規化 InnoDB 結構
-- =======================================================

SET NAMES utf8mb4;

DROP TABLE IF EXISTS `w_item_designated_status`;
CREATE TABLE `w_item_designated_status` (
  `item_id` int NOT NULL COMMENT '道具編號',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '道具名稱/備註',
  `class_id` int NOT NULL DEFAULT 0 COMMENT '職業限制 (0=全職)',
  `skin_id` int NOT NULL DEFAULT 0 COMMENT '外觀變形ID',
  `type` int NOT NULL DEFAULT 0 COMMENT '裝備部位類型',
  `weapon_dmg` int NOT NULL DEFAULT 0 COMMENT '武器追加傷害',
  `weapon_pro` int NOT NULL DEFAULT 0 COMMENT '武器機率發動',
  `add_str` smallint NOT NULL DEFAULT 0 COMMENT '力量增加',
  `add_dex` smallint NOT NULL DEFAULT 0 COMMENT '敏捷增加',
  `add_con` smallint NOT NULL DEFAULT 0 COMMENT '體質增加',
  `add_int` smallint NOT NULL DEFAULT 0 COMMENT '智力增加',
  `add_wis` smallint NOT NULL DEFAULT 0 COMMENT '精神增加',
  `add_cha` smallint NOT NULL DEFAULT 0 COMMENT '魅力增加',
  `add_ac` smallint NOT NULL DEFAULT 0 COMMENT '防禦增加',
  `add_hp` int NOT NULL DEFAULT 0 COMMENT '最大血量增加',
  `add_mp` int NOT NULL DEFAULT 0 COMMENT '最大魔量增加',
  `add_hpr` smallint NOT NULL DEFAULT 0 COMMENT '回血增加',
  `add_mpr` smallint NOT NULL DEFAULT 0 COMMENT '回魔增加',
  `add_dmg` smallint NOT NULL DEFAULT 0 COMMENT '近戰傷害增加',
  `add_hit` smallint NOT NULL DEFAULT 0 COMMENT '近戰命中增加',
  `add_bow_dmg` smallint NOT NULL DEFAULT 0 COMMENT '遠程傷害增加',
  `add_bow_hit` smallint NOT NULL DEFAULT 0 COMMENT '遠程命中增加',
  `add_dmg_r` smallint NOT NULL DEFAULT 0 COMMENT '物理減傷',
  `add_magic_r` smallint NOT NULL DEFAULT 0 COMMENT '魔法減傷',
  `add_mr` smallint NOT NULL DEFAULT 0 COMMENT '魔防增加',
  `add_sp` smallint NOT NULL DEFAULT 0 COMMENT '魔攻(SP)增加',
  `add_fire` smallint NOT NULL DEFAULT 0 COMMENT '火屬性抗性',
  `add_wind` smallint NOT NULL DEFAULT 0 COMMENT '風屬性抗性',
  `add_earth` smallint NOT NULL DEFAULT 0 COMMENT '地屬性抗性',
  `add_water` smallint NOT NULL DEFAULT 0 COMMENT '水屬性抗性',
  `add_stun` smallint NOT NULL DEFAULT 0 COMMENT '昏迷抗性',
  `add_stone` smallint NOT NULL DEFAULT 0 COMMENT '石化抗性',
  `add_sleep` smallint NOT NULL DEFAULT 0 COMMENT '睡眠抗性',
  `add_freeze` smallint NOT NULL DEFAULT 0 COMMENT '凍結抗性',
  `add_sustain` smallint NOT NULL DEFAULT 0 COMMENT '支撐抗性',
  `add_blind` smallint NOT NULL DEFAULT 0 COMMENT '致盲抗性',
  `add_gf` smallint NOT NULL DEFAULT 0 COMMENT '特殊加成',
  `add_exp` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '經驗加成%',
  `effect_icon` int NOT NULL DEFAULT 0 COMMENT '狀態圖示ID',
  `display_title` varchar(255) DEFAULT NULL COMMENT '顯示稱號',
  `poly_id` int NOT NULL DEFAULT 0 COMMENT '變身外觀ID',
  `poly_time` int NOT NULL DEFAULT 0 COMMENT '變身持續時間(秒)',
  PRIMARY KEY (`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='指定道具賦予狀態加成';

